53			t.Fatal(err)
54		}
55		tm := feedingAliasBaseTime()
56		// 两条内容完全相同的投料（连时间与登记人都相同），仅请求编号不同：
57		// 正常规则下它们是两次各自成功的登记，序号分别为 1 和 2。
58		if _, err := s.AddFeeding("feed-1", "B1", "M1", "1.000", tm, "张三"); err != nil {
59			t.Fatal(err)
60		}
61		if _, err := s.AddFeeding("feed-2", "B1", "M1", "1.000", tm, "张三"); err != nil {
62			t.Fatal(err)
