78	// retargetFeedingRequestResult 把正常台账中指定投料请求的保存结果按 mutate
79	// 改写，返回改写后的文件内容。本文件用它把 feed-2 结果的序号从 2 改成 1。
80	func retargetFeedingRequestResult(t *testing.T, good []byte, reqNo string, mutate func(*FeedingView)) []byte {
81		t.Helper()
82		var st persistedState
83		if err := json.Unmarshal(good, &st); err != nil {
84			t.Fatal(err)
85		}
86		req := st.Requests[reqNo]
87		if req == nil {
88			t.Fatalf("正常台账中应存在 %q 请求记录", reqNo)
89		}
90		var view FeedingView
91		if err := json.Unmarshal(req.Result, &view); err != nil {
92			t.Fatal(err)
93		}
94		mutate(&view)
95		raw, err := json.Marshal(view)
96		if err != nil {
97			t.Fatal(err)
98		}
99		req.Result = raw
100		data, err := json.MarshalIndent(&st, "", "  ")
101		if err != nil {
102			t.Fatal(err)
103		}
104		return data
105	}
