107	// aliasFeedingResultToFirst 把 feed-2 保存结果的登记序号改成 1，其余内容
108	// （物料、克数、时间、登记人）保持不变。由于 feed-2 与 feed-1 原提交内容
109	// 完全相同，改完后 feed-2 的结果既符合自己的原提交内容，又与 B1 序号 1
110	// 的实际投料逐项一致——单请求核对全部通过，唯有“两个请求指向同一条投料”
111	// 这一跨请求关系不成立。B1 的两条投料记录与累计数量都保持原样。
112	func aliasFeedingResultToFirst(t *testing.T, good []byte) []byte {
113		t.Helper()
114		return retargetFeedingRequestResult(t, good, "feed-2", func(v *FeedingView) {
115			if v.Seq != 2 {
