```go
// requestRecordMap 是台账 requests 对象的持久化类型……
type requestRecordMap map[string]*requestRecord

func (m *requestRecordMap) UnmarshalJSON(data []byte) error {
	if string(data) == "null" {
		*m = nil
		return nil
	}
	dec := json.NewDecoder(bytes.NewReader(data))
	tok, err := dec.Token()
	if err != nil {
		return err
	}
	if d, ok := tok.(json.Delim); !ok || d != '{' {
		return fmt.Errorf("requests 必须是对象")
	}
	out := make(map[string]*requestRecord)
	for dec.More() {
		ktok, err := dec.Token()
		if err != nil {
			return err
		}
		key, ok := ktok.(string)
		if !ok {
			return fmt.Errorf("requests 的键必须是字符串")
		}
		if _, dup := out[key]; dup {
			return fmt.Errorf("%w: 请求编号 %q 存在多份同编号请求记录", ErrCorruptData, key)
		}
		var rec *requestRecord
		if err := dec.Decode(&rec); err != nil {
			return err
		}
		out[key] = rec
	}
	if _, err := dec.Token(); err != nil { // closing '}'
		return err
	}
	*m = out
	return nil
}
```

Note: json.Decoder.Token() for object keys returns the unescaped string. Yes — keys are unescaped by the decoder. So "req-1" and "req\u002d1" both decode to "req-1" → duplicate detected. 

